#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry trigo. Set Implicit Arguments. Unset Strict Implicit.Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Record point := Point { px : R; py : R }. Definition dist2 A B := (px A - px B)^2 + (py A - py B)^2. Definition dist A B := sqrt (dist2 A B). Variables S R_ T : point. Hypotheses hSR : dist S R_ = 5 /\hST : dist S T = 4 /\hRT : dist R_ T = 3 /\hT : let u := (px S - px T, py S - py T) in let v := (px R_ - px T, py R_ - py T) in u.1 * v.1 + u.2 * v.2 = 0. Definition angle_SRT := let u := (px S - px R_, py S - py R_) in let v := (px T - px R_, py T - py R_) in acos ((u.1 * v.1 + u.2 * v.2) / (sqrt (u.1^+2 + u.2^+2) * sqrt (v.1^+2 + v.2^+2))). Lemma angle_at_R : angle_SRT = PI/6. Proof. by []. Qed.
